/**
 * Billing data shapes. Pure types: invoices are generated by `invoice.ts`, paid through
 * `payments.ts` and planned in bulk by `billing-run.ts`. All amounts are whole US cents.
 */

import type { HealthTier } from "../cost-rates"
import type { BenefitPackage, Quote, WageUnit } from "../types"

export type InvoiceKind = "payroll" | "deposit"

/** Stored status. `paid`, `processing` and `overdue` are derived from payments and dates. */
export type InvoiceStoredStatus = "open" | "void"
export type InvoiceDisplayStatus = "open" | "overdue" | "processing" | "paid" | "void"

export const INVOICE_LINE_CODES = [
  "SALARY",
  "SOCIAL_SECURITY",
  "MEDICARE",
  "FUTA",
  "SUTA",
  "WORKERS_COMP",
  "SERVICE_FEE",
  "HEALTHCARE",
  "RETIREMENT",
  "DEPOSIT",
  "DEPOSIT_WAGE",
  "DEPOSIT_SOCIAL_SECURITY",
  "DEPOSIT_MEDICARE",
  "DEPOSIT_FUTA",
  "DEPOSIT_SUTA",
  "DEPOSIT_WORKERS_COMP",
  "DEPOSIT_SERVICE_FEE",
] as const
export type InvoiceLineCode = (typeof INVOICE_LINE_CODES)[number]

export type InvoiceLineGroup = "wage" | "statutory" | "service_fee" | "benefits" | "deposit"

/**
 * What a payroll line was calculated from, so any amount can be recomputed and audited later.
 * `wageCents` is the gross pay of the period the line was charged on (after proration) and
 * `ytdWageCents` the gross pay earlier in the same tax year. The rest depends on the line.
 */
export type PayrollLineInputs = {
  rateSetId: string
  wageCents: number
  ytdWageCents: number
  [detail: string]: string | number | boolean | null
}

export type DepositLineInputs = {
  rateSetId: string
  /** `quote.totals.committed.monthlyCents`. */
  monthlyCommittedCents: number
  /** `quote.term.committedCents` for a fixed term; `null` when indefinite. */
  termCommittedCents: number | null
  /** A component line only: the quote line's annual cents, the weight of its share of the deposit. */
  annualCents?: number
  /** A component line only: the quote line's own basis ("6.2% up to $184,500"). */
  basis?: string
  [detail: string]: string | number | boolean | null | undefined
}

export type InvoiceLine = {
  code: InvoiceLineCode
  group: InvoiceLineGroup
  description: string
  amountCents: number
  inputs: PayrollLineInputs | DepositLineInputs
}

/** The pay period a payroll invoice bills, and how much of it the person worked. */
export type InvoicePeriod = {
  index: number
  start: string
  end: string
  payDate: string
  taxYear: number
  indexInTaxYear: number
  daysEmployed: number
  periodDays: number
}

export type Invoice = {
  /**
   * Deterministic from what the invoice bills (`payroll:<hireId>:<periodIndex>` or
   * `deposit:<hireId>`), so it doubles as the idempotency key of the billing run.
   */
  id: string
  /** `INV-<year>-<seq>`. */
  number: string
  kind: InvoiceKind
  companyId: string
  hireId: string
  /** Absent for a deposit. */
  period: InvoicePeriod | null
  issueDate: string
  dueDate: string
  currency: "USD"
  rateSetId: string
  payCalendarId: string
  lines: InvoiceLine[]
  /** Sum of the lines. */
  totalCents: number
  status: InvoiceStoredStatus
}

export type PaymentStatus = "initiated" | "succeeded" | "failed"

/** What a saved payment method looks like to the billing screens; never the full number. */
export type SavedPaymentMethod = {
  id: string
  type: "card" | "us_bank_account"
  /** Card brand or bank name. */
  label: string
  last4: string
  expMonth: number | null
  expYear: number | null
}

export type PaymentAllocation = {
  invoiceId: string
  amountCents: number
}

export type Payment = {
  id: string
  companyId: string
  status: PaymentStatus
  method: SavedPaymentMethod | null
  allocations: PaymentAllocation[]
  totalCents: number
  initiatedAt: string
  /** When it succeeded; `null` unless `status` is `succeeded`. */
  settledAt: string | null
  /** When it failed; `null` unless `status` is `failed`. */
  failedAt: string | null
  failureReason: string | null
}

/** What a worker has chosen for benefits; invoices bill benefits only when `enrolled`. */
export type BenefitElectionState = {
  enrolled: boolean
  /** `null` declines health coverage. */
  healthTier: HealthTier | null
  /** Percent of gross pay deferred to the 401(k); `null` declines. */
  retirementDeferralPct: number | null
}

export const DECLINED_ELECTIONS: BenefitElectionState = {
  enrolled: false,
  healthTier: null,
  retirementDeferralPct: null,
}

export type BillingCompany = { id: string }

/** The frozen terms of a hire that invoices are calculated from. */
export type BillingHireSnapshot = {
  hireId: string
  wageCents: number
  wageUnit: WageUnit
  stateCode: string
  markupPct: number
  package: BenefitPackage
  rateSetId: string
  /** First day of employment. */
  startDate: string
  /** Fixed-term end date (inclusive); `null` for an indefinite hire. */
  termEndDate: string | null
  /** Last working day after a termination (inclusive); `null` while employed. */
  lastWorkingDay: string | null
}

export type BillingHire = BillingHireSnapshot & {
  companyId: string
  /** The day the order was placed: the deposit invoice is issued then. */
  hiredOn: string
  /** The quote frozen in the policy snapshot. Priced from the snapshot fields when absent. */
  quote?: Quote
}
